<script setup lang="ts">
import { ref } from 'vue'; import { useRoute } from 'vue-router'; import { NButton, NDrawer, NDrawerContent } from 'naive-ui'; import { useI18n } from 'vue-i18n'; import Navigation from './Navigation.vue'; import DemoControls from './DemoControls.vue'; import DemoNotice from '../components/DemoNotice.vue'; import { pageLocation } from './router'; import type { PageName } from './routes'; const { t } = useI18n(); const route = useRoute(); const open = ref(false); function focusMain() { document.getElementById('main-content')?.focus() }
